<template>
  <main class="lesson">
    <header class="top"><strong>✳ Inquiry Studio <span>／ 教案工作台</span></strong><div class="actions"><span role="status">{{ dirty ? '有未保存的修改' : document ? '已保存到服务器' : '新建教案' }}</span><button :disabled="busy" @click="leave">返回首页</button><button v-if="document" :disabled="busy" @click="showVersions">历史版本</button><button v-if="document" :disabled="busy || !dirty" @click="save">保存</button><button v-if="document" class="primary" :disabled="busy || dirty" @click="exportWord">导出 Word</button></div></header>
    <p v-if="error" class="alert" role="alert">{{ error }}</p>
    <section v-if="!document" class="import">
      <p class="eyebrow">LESSON WORKSPACE</p><h1>上传你的教案，看看还有哪些提升空间</h1>
      <p class="notice">可导入并编辑教案，未选择参考资料时可以使用通用模型分析。</p>
      <div class="import-grid"><article class="card full"><h2>导入教案</h2><p>上传 Word（.docx）或 UTF-8 文本（.txt），也可以直接粘贴正文。文件最大 5 MB；旧版 .doc 请先转换为 .docx。</p><p class="muted">Word 导入正文和表格文字，原有排版、图片等内容不会保留，请检查后继续。</p><input type="file" accept=".docx,.txt,application/vnd.openxmlformats-officedocument.wordprocessingml.document,text/plain" :disabled="busy" aria-label="选择教案文件" @change="readText"><p v-if="importedName" class="muted">已导入：{{ importedName }}</p><label for="lessonText">教案正文</label><textarea id="lessonText" v-model="inputText" rows="12" maxlength="100000" :disabled="busy" aria-label="教案正文" placeholder="上传文件，或在这里粘贴完整教案……"></textarea><div class="actions"><button class="primary" :disabled="busy || !inputText.trim()" @click="create">保存并进入工作台</button></div></article></div>
    </section>
    <div v-else class="workspace markdown-workspace" :class="{'show-side': mobileSide}">
      <section class="editor markdown-editor"><div class="toolbar"><strong>教案全文 · Markdown</strong><span>版本 {{ document.version }}</span><button v-if="lastApplied" :disabled="markdown !== lastApplied.after || busy" @click="undoSuggestion">撤销本次采纳</button><button class="mobile" @click="mobileSide = true">打开教学助手</button></div><p class="editor-hint">直接编辑全文；选中一段后可在右侧请求优化。保存后可分析、导出或恢复历史版本。</p><textarea ref="markdownEditor" v-model="markdown" class="markdown-input" :disabled="busy || document.locked" aria-label="教案 Markdown 全文" spellcheck="false" @select="captureSelection" @input="clearSelection" ></textarea></section>
      <LessonAssistant :workspace-id="workspaceId" :artifact-id="document.id" :version="document.version" :dirty="dirty" :locked="document.locked" :source-count="content!.selected_source_ids.length" :selected-text="selectedText" :selection-key="selectionKey" @close="mobileSide = false" @sources="selectorOpen = true" @apply="applySuggestion" />
    </div>
    <div v-if="selectorOpen && content" class="backdrop" @click.self="selectorOpen = false" @keydown.esc="selectorOpen = false"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="source-title"><div class="section-head"><h2 id="source-title">选择授权教学资料</h2><button @click="selectorOpen = false" aria-label="关闭">×</button></div><p>仅显示当前可用的授权资料；资料并非独立知识库。</p><input v-model="search" placeholder="搜索资料" aria-label="搜索资料"><p v-if="!filteredSources.length" class="muted">没有匹配的授权资料。</p><label v-for="source in filteredSources" :key="source.id" class="source"><input type="checkbox" :checked="content.selected_source_ids.includes(source.id)" :disabled="busy || document?.locked || (!content.selected_source_ids.includes(source.id) && content.selected_source_ids.length >= 20)" @change="toggleSource(source.id)"> {{ source.title }}</label><p v-for="id in unavailableSources" :key="id" class="alert">所选资料已不可用或权限已变更。<button @click="toggleSource(id)">移除</button></p><p>已选 {{ content.selected_source_ids.length }} 项</p><button class="primary" @click="selectorOpen = false">完成</button></section></div>
    <div v-if="versionsOpen && document" class="backdrop" @click.self="versionsOpen = false" @keydown.esc="versionsOpen = false"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="version-title"><div class="section-head"><h2 id="version-title">历史版本</h2><button @click="versionsOpen = false" aria-label="关闭">×</button></div><p>恢复会创建新版本；当前未保存修改需要先处理。</p><p v-if="!versions.length" class="muted">暂无版本。</p><div v-for="version in versions" :key="version.version" class="version"><div><strong>版本 {{ version.version }}</strong> · {{ version.created_at }}<details><summary>查看内容</summary><div v-for="section in version.content.sections" :key="section.id"><strong>{{ section.title }}</strong><p v-for="p in section.paragraphs" :key="p.id">{{ p.text }}</p></div></details></div><button :disabled="busy || dirty || document.locked || version.version === document.version" @click="restore(version.version)">恢复</button></div></section></div>
  </main>
</template>
<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue';
import LessonAssistant from './LessonAssistant.vue';
import { request, json, downloadLesson, type Artifact, type Source, type Workspace } from './api';

type Paragraph = { id: string; text: string };
type Section = { id: string; title: string; paragraphs: Paragraph[] };
type Content = { title: string; sections: Section[]; selected_source_ids: string[] };
type Version = { version: number; created_at: string; content: Content };
const props = defineProps<{initialWorkspace: Workspace | null; sources: Source[]}>();
const emit = defineEmits<{close: []}>();
const workspaceId = ref(props.initialWorkspace?.id || '');
const document = ref<Artifact | null>(props.initialWorkspace?.artifacts.find(a => a.type === 'LessonDocument') || null);
const copy = <T,>(value: T): T => JSON.parse(JSON.stringify(value)) as T;
const content = ref<Content | null>(document.value ? copy(document.value.content as unknown as Content) : null);
function fullText(value: Content): string { return value.sections.map(s => { const lines = s.paragraphs.map(p => p.text); if (s.title !== '教案原文' && lines[0]?.trim().replace(/[：:]$/, '') !== s.title) lines.unshift('## ' + s.title); return lines.join('\n'); }).join('\n'); }
const markdown = ref(content.value ? fullText(content.value) : '');
const baseline = ref(content.value ? JSON.stringify(content.value) : '');
const baselineMarkdown = ref(content.value ? content.value.sections.flatMap(s => s.paragraphs.map(p => p.text)).join('\n') : '');
const dirty = computed(() => content.value !== null && (JSON.stringify(content.value) !== baseline.value || markdown.value !== baselineMarkdown.value));
const markdownEditor = ref<HTMLTextAreaElement | null>(null), selectedText = ref(''), selectionStart = ref(0), selectionEnd = ref(0);
const selectionKey = computed(() => `${selectionStart.value}:${selectionEnd.value}:${selectedText.value}`);
const lastApplied = ref<{before:string;after:string} | null>(null);
function undoSuggestion() { if (lastApplied.value && markdown.value === lastApplied.value.after) { markdown.value = lastApplied.value.before; lastApplied.value = null; clearSelection(); } }
function captureSelection() { const el = markdownEditor.value; if (!el) return; selectionStart.value = el.selectionStart; selectionEnd.value = el.selectionEnd; selectedText.value = el.value.slice(el.selectionStart, el.selectionEnd); }
function clearSelection() { selectedText.value = ''; selectionStart.value = 0; selectionEnd.value = 0; }
function applySuggestion(text: string, selection: string) { if (document.value?.locked || !selection || markdown.value.slice(selectionStart.value, selectionEnd.value) !== selection) { error.value = '教案已锁定或选中内容已变化，无法采纳。'; return; } const before = markdown.value; markdown.value = before.slice(0, selectionStart.value) + text + before.slice(selectionEnd.value); lastApplied.value = {before, after:markdown.value}; clearSelection(); }
function contentForSave(value: Content): Content { if (markdown.value === baselineMarkdown.value) return copy(value); const previous = value.sections.flatMap(section => section.paragraphs); const lines = markdown.value.split('\n'); if (lines.length === previous.length && fullText(value) === baselineMarkdown.value) { const result = copy(value); let index = 0; for (const section of result.sections) for (const paragraph of section.paragraphs) paragraph.text = lines[index++]!; return result; } return {...copy(value), sections:[{id:value.sections[0]!.id,title:'教案原文',paragraphs:lines.map((text, index) => ({id:previous[index]?.text === text ? previous[index]!.id : 'para_' + crypto.randomUUID(),text}))}]}; }
function resetBaseline() { baseline.value = JSON.stringify(content.value); baselineMarkdown.value = content.value?.sections.flatMap(s => s.paragraphs.map(p => p.text)).join('\n') || ''; }

const importedName = ref(''), inputText = ref(''), error = ref(''), busy = ref(false), current = ref(content.value?.sections[0]?.id || '');
const selectorOpen = ref(false), versionsOpen = ref(false), search = ref(''), mobileSide = ref(false);
const versions = ref<Version[]>([]), undoStack = ref<Content[]>([]), redoStack = ref<Content[]>([]);
const filteredSources = computed(() => props.sources.filter(s => s.title.toLowerCase().includes(search.value.trim().toLowerCase())));
const unavailableSources = computed(() => content.value?.selected_source_ids.filter(id => !props.sources.some(s => s.id === id)) || []);
const path = () => `/api/inquiry-workspaces/${encodeURIComponent(workspaceId.value)}/lesson-document/${encodeURIComponent(document.value!.id)}`;
function message(e: unknown) { error.value = e instanceof Error ? e.message : '操作失败，请重试。'; }
function checkpoint() { if (!content.value) return; const last = undoStack.value.at(-1); if (!last || JSON.stringify(last) !== JSON.stringify(content.value)) { undoStack.value.push(copy(content.value)); if (undoStack.value.length > 100) undoStack.value.shift(); redoStack.value = []; } }
function undo() { if (!content.value || !undoStack.value.length) return; redoStack.value.push(copy(content.value)); content.value = undoStack.value.pop()!; }
function redo() { if (!content.value || !redoStack.value.length) return; undoStack.value.push(copy(content.value)); content.value = redoStack.value.pop()!; }
function jump(id: string) { current.value = id; globalThis.document.getElementById(id)?.scrollIntoView({behavior: 'smooth', block: 'start'}); }
function addSection() { if (!content.value || document.value?.locked || content.value.sections.length >= 100) return; checkpoint(); const id = 'sec_' + crypto.randomUUID(); content.value.sections.push({id, title:'新章节', paragraphs:[{id:'para_' + crypto.randomUUID(), text:''}]}); current.value = id; }
function deleteSection(id: string) { if (!content.value || content.value.sections.length <= 1 || !window.confirm('删除此章节及其正文？')) return; checkpoint(); content.value.sections = content.value.sections.filter(s => s.id !== id); current.value = content.value.sections[0]?.id || ''; }
function addParagraph(id: string) { if (!content.value || content.value.sections.reduce((n,s) => n + s.paragraphs.length, 0) >= 1000) { error.value = '最多支持 1000 个段落。'; return; } checkpoint(); content.value.sections.find(s => s.id === id)?.paragraphs.push({id:'para_' + crypto.randomUUID(), text:''}); }
function deleteParagraph(sectionId: string, paragraphId: string) { const section = content.value?.sections.find(s => s.id === sectionId); if (!section || section.paragraphs.length <= 1 || !window.confirm('删除这个段落？')) return; checkpoint(); section.paragraphs = section.paragraphs.filter(p => p.id !== paragraphId); }
function toggleSource(id: string) { if (!content.value || busy.value || document.value?.locked) return; checkpoint(); const ids = content.value.selected_source_ids; content.value.selected_source_ids = ids.includes(id) ? ids.filter(x => x !== id) : [...ids,id]; }
async function readText(event: Event) { const input = event.target as HTMLInputElement, file = input.files?.[0]; if (!file) return; input.value = ''; if (!/\.(txt|docx)$/i.test(file.name) || file.size > 5 * 1024 * 1024) { error.value = '请选择不超过 5 MB 的 TXT 或 DOCX 文件；旧版 DOC 请先转换。'; return; } if (inputText.value.trim() && !window.confirm('导入文件会替换当前正文，确定继续吗？')) return; busy.value = true; error.value = ''; try { const form = new FormData(); form.append('file', file); const result = await request<{text:string}>('/api/inquiry-scenes/lesson-import', {method:'POST', body:form}); inputText.value = result.text; importedName.value = file.name; } catch (e) { message(e); } finally { busy.value = false; } }
async function create() { if (busy.value || !inputText.value.trim()) return; const title = (importedName.value.replace(/\.(txt|docx)$/i, '').trim() || inputText.value.split(/\r?\n/).find(line => line.trim())?.trim() || '未命名教案').slice(0, 200); busy.value = true; error.value = ''; try { if (!workspaceId.value) { const workspace = await request<{id:string}>('/api/inquiry-workspaces', json('POST', {title})); workspaceId.value = workspace.id; } document.value = await request<Artifact>(`/api/inquiry-workspaces/${encodeURIComponent(workspaceId.value)}/lesson-document`, json('POST', {title,text:inputText.value})); content.value = copy(document.value.content as unknown as Content); markdown.value = fullText(content.value); resetBaseline(); current.value = content.value.sections[0]?.id || ''; } catch (e) { message(e); } finally { busy.value = false; } }
async function save() { if (!document.value || !content.value || busy.value) return; busy.value = true; error.value = ''; try { const result = await request<Artifact>(path(), json('PUT', {expected_version:document.value.version,content:contentForSave(content.value)})); document.value = result; content.value = copy(result.content as unknown as Content); markdown.value = fullText(content.value); resetBaseline(); clearSelection(); } catch (e) { message(e); } finally { busy.value = false; } }
async function showVersions() { if (!document.value) return; try { versions.value = await request<Version[]>(`/api/inquiry-workspaces/${encodeURIComponent(workspaceId.value)}/artifacts/${encodeURIComponent(document.value.id)}/versions`); versionsOpen.value = true; } catch (e) { message(e); } }
async function restore(version: number) { if (!document.value || document.value.locked || dirty.value || !window.confirm('恢复这个版本并创建新版本？')) return; busy.value = true; try { const result = await request<Artifact>(`/api/inquiry-workspaces/${encodeURIComponent(workspaceId.value)}/artifacts/${encodeURIComponent(document.value.id)}/restore`, json('POST',{expected_version:document.value.version,version})); document.value = result; content.value = copy(result.content as unknown as Content); markdown.value = fullText(content.value); resetBaseline(); clearSelection(); lastApplied.value = null; undoStack.value = []; redoStack.value = []; current.value = content.value.sections[0]?.id || ''; versionsOpen.value = false; } catch (e) { message(e); } finally { busy.value = false; } }
async function exportWord() { if (!document.value || dirty.value) return; busy.value = true; try { await downloadLesson(workspaceId.value, document.value.id); } catch (e) { message(e); } finally { busy.value = false; } }
function leave() { if ((dirty.value || (!document.value && !!inputText.value.trim())) && !window.confirm('当前内容尚未保存，确定离开吗？')) return; emit('close'); }
function beforeUnload(event: BeforeUnloadEvent) { if (dirty.value || (!document.value && inputText.value.trim())) { event.preventDefault(); event.returnValue = ''; } }
onMounted(() => window.addEventListener('beforeunload', beforeUnload));
onBeforeUnmount(() => window.removeEventListener('beforeunload', beforeUnload));
</script>
<style scoped>
.lesson{min-height:100vh;background:#f5f8f6;color:#183a33;font:15px/1.6 system-ui,sans-serif}.lesson *{box-sizing:border-box}.lesson button,.lesson input,.lesson textarea{font:inherit}.lesson button{border:1px solid #d5e4dc;border-radius:8px;background:#fff;color:#183a33;padding:8px 12px;cursor:pointer}.lesson button:disabled{opacity:.5;cursor:not-allowed}.lesson button:focus-visible,.lesson input:focus-visible,.lesson textarea:focus-visible{outline:3px solid #9dd3bf}.lesson .primary{background:#27816c;border-color:#27816c;color:white}.top{position:sticky;top:0;z-index:4;background:white;border-bottom:1px solid #d5e4dc;padding:14px clamp(16px,3vw,48px);display:flex;align-items:center;justify-content:space-between;gap:12px}.top strong{font-size:19px}.top strong span,.muted,.actions span{color:#70877c;font-size:13px}.actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.alert{color:#9c3d31;background:#fff2ed;border:1px solid #edc8b9;padding:10px 14px;border-radius:8px}.notice{background:#edf7f1;border:1px solid #d5e4dc;padding:12px;border-radius:9px}.eyebrow{font-size:12px;letter-spacing:.14em;color:#27816c}.import{max-width:1200px;margin:50px auto;padding:0 24px}.import h1{font-size:clamp(28px,3vw,40px)}.import-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:20px}.card,.outline,.editor,.side{background:white;border:1px solid #d5e4dc;border-radius:12px}.card{padding:22px}.card p{color:#70877c}.full{grid-column:1/-1}.card input:not([type=file]),.card textarea,.dialog>input{width:100%;border:1px solid #d5e4dc;border-radius:8px;padding:10px}.card textarea{resize:vertical}.workspace{display:grid;grid-template-columns:230px minmax(0,1fr) 380px;gap:16px;padding:18px clamp(16px,2vw,36px);align-items:start}.outline,.side{position:sticky;top:86px;max-height:calc(100vh - 106px);overflow:auto;padding:18px}.outline button{display:block;text-align:left;width:100%;border:0}.outline button.active{background:#edf7f1;color:#27816c}.editor{min-width:0;overflow:hidden}.toolbar{display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:12px;border-bottom:1px solid #d5e4dc}.toolbar span{color:#70877c;font-size:12px}.compact-outline{display:none;max-width:160px;padding:8px;border:1px solid #d5e4dc;border-radius:8px}.editor-scroll{max-height:calc(100vh - 165px);overflow:auto;min-height:400px}.paper{max-width:1000px;margin:auto;padding:clamp(24px,5vw,65px)}.title-label{display:block;color:#70877c}.title-label input{font-size:28px;font-weight:700;border:0;display:block;width:100%;color:#183a33}.paper fieldset{border:0;padding:0;margin:0}.doc-section{padding:20px 0;border-bottom:1px solid #edf2ef;scroll-margin-top:90px}.section-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.section-head input{border:0;font-size:19px;font-weight:700;width:100%;color:#183a33}.doc-section textarea{display:block;width:100%;border:1px solid transparent;border-radius:6px;padding:8px;resize:vertical;line-height:1.7}.doc-section textarea:focus{border-color:#d5e4dc}.paragraph{display:flex;align-items:start;gap:8px}.paragraph button{white-space:nowrap;font-size:12px}.side h2{font-size:19px}.side h3{margin-top:24px}.side ul{padding-left:20px}.backdrop{position:fixed;inset:0;z-index:10;background:#183a3366;display:grid;place-items:center;padding:16px}.dialog{width:min(640px,100%);max-height:85vh;overflow:auto;background:white;border-radius:14px;padding:24px}.source{display:block;padding:10px;border-bottom:1px solid #edf2ef}.version{display:flex;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid #edf2ef}.version p{white-space:pre-wrap;overflow-wrap:anywhere}.mobile{display:none}@media(max-width:1100px){.workspace{grid-template-columns:minmax(0,1fr) 340px}.outline{display:none}.compact-outline{display:block}}@media(max-width:700px){.top{flex-wrap:wrap}.import-grid{grid-template-columns:1fr}.full{grid-column:auto}.workspace{display:block;padding:12px}.workspace .side{display:none}.workspace.show-side .editor{display:none}.workspace.show-side .side{display:block;position:static;max-height:none}.editor-scroll{max-height:none}.mobile{display:inline-block}.paper{padding:24px}.actions span{display:none}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}

.markdown-workspace{grid-template-columns:minmax(0,1fr) 380px}.markdown-editor{display:flex;flex-direction:column;min-height:calc(100vh - 106px)}.editor-hint{margin:0;padding:12px 18px;color:#70877c;font-size:13px}.markdown-input{display:block;flex:1;width:100%;min-height:65vh;padding:24px clamp(20px,4vw,56px);border:0;resize:vertical;outline:0;color:#183a33;background:#fff;font:15px/1.8 ui-monospace,Consolas,monospace;white-space:pre-wrap}.markdown-input:focus{outline:2px solid #9dd3bf;outline-offset:-2px}@media(max-width:700px){.markdown-workspace{display:block}.markdown-workspace :deep(.assistant){display:none}.markdown-workspace.show-side .markdown-editor{display:none}.markdown-workspace.show-side :deep(.assistant){display:flex}.markdown-input{min-height:55vh}}
</style>
